-- GENERATED by pipeline/make_dbt_staging.py from sources.json
-- and the extract's club folders; edit them or it, never this file.
{{ config(materialized='table') }}
-- Every points of interest row of the clubs' registered ArcGIS layers that
-- pipeline/make_dbt_staging.py stages, one row each, unfiltered: a `union
-- all by name` of every stg_<folder>__points_of_interest it writes. The
-- branch list is the registry's, written by the generator from sources.json
-- and the extract's club folders, so a layer registered later joins by
-- running it again. Nothing here is filtered for publication: whatever
-- reads it keeps int_sources__publication's verdict, the one home of
-- may_publish.
select
    source_key,
    club,
    poi_key,
    name,
    category,
    source_id,
    geom,
    properties,
    _loaded_at
from {{ ref('stg_alaska_trails__points_of_interest') }}
